package com.rustraid.data
import com.google.firebase.database.*
import com.rustraid.model.AlertSnapshot
import com.rustraid.model.AlertState
import com.rustraid.model.ActivityEntry
import com.rustraid.model.AppSettings
import java.time.Instant
class FirebaseRepository(private val laptopId:String) {
 private val root=FirebaseDatabase.getInstance().getReference("laptops").child(laptopId)
 fun watchAlarm(onSnapshot:(AlertSnapshot)->Unit,onError:()->Unit):ValueEventListener{val listener=object:ValueEventListener{override fun onDataChange(s:DataSnapshot){val active=s.child("alarm_active").getValue(Boolean::class.java)?:false;val cooldown=s.child("cooldown_until").getValue(String::class.java);val state=when{active->AlertState.RAID_ACTIVE;cooldown?.let{runCatching{Instant.parse(it).isAfter(Instant.now())}.getOrDefault(false)}==true->AlertState.COOLDOWN;else->AlertState.MONITORING};onSnapshot(AlertSnapshot(state,s.child("triggered_at").getValue(String::class.java),cooldown,s.child("message").getValue(String::class.java)?:""))};override fun onCancelled(error:DatabaseError){onError()}};root.child("raid_alarm").addValueEventListener(listener);return listener}
 fun removeAlarmListener(listener:ValueEventListener){root.child("raid_alarm").removeEventListener(listener)}
 fun watchSettings(onSettings:(AppSettings)->Unit):ValueEventListener{val listener=object:ValueEventListener{override fun onDataChange(s:DataSnapshot){onSettings(AppSettings(alertMode=s.child("alert_mode").getValue(String::class.java)?:"critical",deviceTarget=s.child("device_target").getValue(String::class.java)?:"both",cooldownMinutes=(s.child("cooldown_duration_minutes").getValue(Long::class.java)?:120).toInt(),screenFlash=s.child("screen_flash").getValue(Boolean::class.java)?:true,vibration=s.child("vibration").getValue(Boolean::class.java)?:true,volumeOverride=s.child("volume_override").getValue(Boolean::class.java)?:true,quietHoursEnabled=s.child("quiet_hours_enabled").getValue(Boolean::class.java)?:false,quietHoursStart=s.child("quiet_hours_start").getValue(String::class.java)?:"23:00",quietHoursEnd=s.child("quiet_hours_end").getValue(String::class.java)?:"07:00",autoSilenceMinutes=(s.child("auto_silence_minutes").getValue(Long::class.java)?:5).toInt(),amoledBlack=s.child("amoled_black").getValue(Boolean::class.java)?:false))};override fun onCancelled(error:DatabaseError){}};root.child("settings").addValueEventListener(listener);return listener}
 fun removeSettingsListener(listener:ValueEventListener){root.child("settings").removeEventListener(listener)}
 fun updateSettings(values:Map<String,Any>){root.child("settings").updateChildren(values)}
 fun watchActivity(onEntries:(List<ActivityEntry>)->Unit):ValueEventListener{val listener=object:ValueEventListener{override fun onDataChange(s:DataSnapshot){onEntries(s.children.map{child->ActivityEntry(child.key?:"",child.child("timestamp").getValue(String::class.java)?:"",child.child("description").getValue(String::class.java)?:"",child.child("type").getValue(String::class.java)?:"system")}.sortedByDescending{it.timestamp}.take(100))};override fun onCancelled(error:DatabaseError){}};root.child("activity_log/entries").addValueEventListener(listener);return listener}
 fun removeActivityListener(listener:ValueEventListener){root.child("activity_log/entries").removeEventListener(listener)}
 fun watchPairAcceptance(phoneId:String,onAccepted:()->Unit):ValueEventListener{val listener=object:ValueEventListener{override fun onDataChange(s:DataSnapshot){if(s.getValue(String::class.java)==phoneId)onAccepted()};override fun onCancelled(error:DatabaseError){}};root.child("app_meta/paired_phone_id").addValueEventListener(listener);return listener}
 fun removePairAcceptanceListener(listener:ValueEventListener){root.child("app_meta/paired_phone_id").removeEventListener(listener)}
 fun acknowledge(source:String="phone"){root.child("settings/cooldown_duration_minutes").get().addOnSuccessListener { snap ->val minutes=(snap.getValue(Long::class.java)?:120L).coerceIn(1,1440);val until=Instant.ofEpochMilli(System.currentTimeMillis()+minutes*60_000).toString();root.child("raid_alarm").updateChildren(mapOf("alarm_active" to false,"acknowledged" to true,"acknowledged_by" to source,"acknowledged_at" to Instant.now().toString(),"cooldown_until" to until))}.addOnFailureListener {root.child("raid_alarm").updateChildren(mapOf("alarm_active" to false,"acknowledged" to true,"acknowledged_by" to source))}}
 fun setMode(mode:String){updateSettings(mapOf("alert_mode" to mode))}
 fun triggerLocalTest(){root.child("raid_alarm").updateChildren(mapOf("alarm_active" to true,"acknowledged" to false,"triggered_at" to Instant.now().toString(),"message" to "Phone test alert","device_target" to "phone","alert_mode" to "critical"))}
 fun heartbeat(){root.child("app_meta/phone_last_seen").setValue(Instant.now().toString())}
}
